//! Structured, append-only execution events. The UI consumes these instead of raw process output.

use crate::model::NodeId;
use serde::{Deserialize, Serialize};

/// Who produced the event. Lets the UI distinguish real provider activity from
/// messages generated by Boiler Room itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Source {
    Provider,
    Application,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum EventKind {
    RunCreated {
        request: String,
    },
    RunStarted,
    RunPaused,
    RunResumed,
    RunCancelled,
    RunCompleted,
    RunFailed {
        reason: String,
    },
    TaskCreated,
    TaskAssigned {
        provider: String,
    },
    TaskBlocked {
        reason: String,
    },
    TaskRetried {
        attempt: u32,
        reason: String,
    },
    TaskCompleted,
    TaskFailed {
        reason: String,
    },
    WorkerStarted {
        session_id: Option<String>,
    },
    WorkerOutput {
        text: String,
    },
    WorkerToolCall {
        tool: String,
        input: serde_json::Value,
    },
    WorkerExited {
        code: Option<i32>,
    },
    ValidationPassed,
    ValidationFailed {
        reason: String,
    },
    ReworkTriggered {
        from: NodeId,
        to: NodeId,
        traversal: u32,
    },
    ApprovalRequested {
        approval_id: String,
        action: String,
    },
    ApprovalGranted {
        approval_id: String,
    },
    ApprovalRejected {
        approval_id: String,
    },
}

/// An event before persistence (no sequence number yet).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct NewEvent {
    pub run_id: String,
    pub node_id: Option<NodeId>,
    pub source: Source,
    pub kind: EventKind,
}

/// A persisted event; `seq` is a global, strictly increasing order.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Event {
    pub seq: i64,
    pub ts_ms: i64,
    #[serde(flatten)]
    pub event: NewEvent,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn kind_serializes_with_type_tag() {
        let j = serde_json::to_value(EventKind::TaskBlocked { reason: "x".into() }).unwrap();
        assert_eq!(
            j,
            serde_json::json!({"type": "task_blocked", "reason": "x"})
        );
        let back: EventKind = serde_json::from_value(j).unwrap();
        assert_eq!(back, EventKind::TaskBlocked { reason: "x".into() });
    }
}
